const session = await client.createSession({
  model: "gpt-4.1",
  customAgents: [
    {
      name: "triage",
      displayName: "Triage Agent",
      description: "Classifies incident symptoms and reads logs",
      tools: ["grep", "glob", "view"],
      prompt: "Identify likely root cause. Do not edit files."
    },
    {
      name: "patch-planner",
      displayName: "Patch Planner",
      description: "Plans targeted code fixes for the active incident",
      tools: ["view", "edit"],
      prompt: "Prepare minimal remediation changes and explain risks."
    },
    {
      name: "rollback",
      displayName: "Rollback Agent",
      description: "Rolls back risky changes during production incidents",
      tools: null,
      infer: true,
      prompt: "Revert the suspected bad change and update the incident notes."
    }
  ]
});

session.on((event) => {
  if (event.type === "subagent.selected") {
    console.log(event.data.agentDisplayName);
  }
});

{
  "mcpServers": {
    "tracker": {
      "type": "local",
