}

{
  "mcpServers": {
    "tracker": {
      "type": "local",
      "command": "npx",
      "args": ["-y", "@example/tracker-mcp"],
      "tools": ["*"]
    }
  }
}

{
  "mcpServers": {
    "github-mcp-server": {
      "type": "http",
      "url": "https://api.githubcopilot.com/mcp/",
      "tools": ["*"],
      "headers": {
        "Authorization": "Bearer ${GITHUB_TOKEN}"
      }
    },
    "sentry": {
      "type": "stdio",
      "command": "npx",
      "args": ["-y", "@sentry/mcp-server"],
      "tools": ["*"],
      "env": {
        "SENTRY_AUTH_TOKEN": "${SENTRY_AUTH_TOKEN}"
      }
    }
  }
}

session.on((event) => {
  if (event.type === "subagent.selected") {
    audit.write({
      agent: event.data.agentName,
      tools: event.data.tools,
      status: "selected",
      at: event.timestamp
    });
  }

  if (event.type === "subagent.deselected") {
    audit.write({
      status: "returned-to-parent",
      at: event.timestamp
    });
  }
});

type AgentNode = {
  name: string;
  displayName?: string;
  status: "running" | "completed" | "failed";
  error?: string;
};

const agentNodes = new Map<string, AgentNode>();

session.on((event) => {
  if (event.type === "subagent.selected") {
    agentNodes.set(event.data.agentName, {
      name: event.data.agentName,
      displayName: event.data.agentDisplayName,
      status: "running",
    });
  }

  if (event.type === "subagent.completed") {
    const node = agentNodes.get(event.data.agentName);
    if (node) node.status = "completed";
  }

  if (event.type === "subagent.failed") {
    logger.warn(`Sub-agent failed: ${event.data.error}`);
  }
});

const runs = new Map<string, { status: string; error?: string }>();

session.on("event", (event) => {
  if (event.type === "subagent.started") {
    runs.set(event.data.agentName, { status: "running" });
  }

  if (event.type === "subagent.completed") {
    runs.set(event.data.agentName, { status: "completed" });
  }

  if (event.type === "subagent.failed") {
    runs.set(event.data.agentName, {
      status: "failed",
      error: event.data.error
    });
  }
});

{
  "mcpServers": {
    "experiments": {
      "type": "http",
      "url": "https://ml-metadata.contoso.example/mcp",
      "resources": ["experiments://latest"],
      "prompts": ["compare-runs"]
    }
  }
}

const session = await client.createSession({
  model: "gpt-4.1",
  customAgents: [
    {
      name: "cleanup",
      displayName: "Cleanup Agent",
      description: "Deletes obsolete files, removes dead code, and prunes unused assets",
      tools: null,
      prompt: "Clean up the repository after incidents. Remove files that appear unused."
    }
  ],
  onPermissionRequest: async () => ({ kind: "approved" })
});

{
  "mcpServers": {
    "incidents": {
      "type": "http",
      "url": "https://incidents.contoso.example/mcp",
      "tools": ["*"],
      "headers": {
        "Authorization": "Bearer $INCIDENTS_TOKEN"
      },
      "oauth": {
        "clientId": "copilot-agent"
      }
    }
  }
}

const session = await client.createSession({
  availableTools: ["read", "edit", "execute", "agent"],
  excludedTools: ["execute"],
  customAgents: [
    {
      name: "test-runner",
      description: "Runs test commands and summarizes failures",
      tools: ["read", "execute"],
      prompt: "Run only project test commands and report failures."
    }
  ]
});

const activeAgents = new Map<string, { name: string; status: string }>();

session.on((event) => {
  if (event.type === "subagent.started") {
    activeAgents.set(event.data.agentName, {
      name: event.data.agentName,
      status: "running"
    });
  }

  if (event.type === "subagent.completed") {
    const node = activeAgents.get(event.data.agentName);
    if (node) node.status = "completed";
  }

  if (event.type === "subagent.failed") {
    const node = activeAgents.get(event.data.agentName);
    if (node) node.status = "failed";
  }
});

{
  "mcpServers": {
    "servicedesk": {
      "command": "npx",
      "args": ["-y", "@contoso/servicedesk-mcp", "--token", "${input:ticketToken}"],
      "inputs": [
        {
          "id": "ticketToken",
          "type": "promptString",
          "password": true
        }
      ],
      "envFile": ".env.local"
